import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.1C62pOns.js";const s="/pro-agent-hub-installer/capturas/en/planejadores-detalhe.png",r="/pro-agent-hub-installer/capturas/en/planejadores-execucao.png",b=JSON.parse('{"title":"Planners","description":"","frontmatter":{},"headers":[],"relativePath":"en/interface/planejadores.md","filePath":"en/interface/planejadores.md","lastUpdated":1787856241000}'),i={name:"en/interface/planejadores.md"};function l(d,e,h,c,p,u){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="planners" tabindex="-1">Planners <a class="header-anchor" href="#planners" aria-label="Permalink to &quot;Planners&quot;">​</a></h1><p>A <strong>workflow</strong> knows the path in advance; you drew every step. A <strong>planner</strong> does not: you give it the goal and it works out the path, one step at a time.</p><p>The cycle is always the same — <strong>plan → act → observe → evaluate → replan</strong> — and it repeats until the success criterion is met or a limit is hit.</p><p>Use a planner when the steps depend on what is found along the way. When you already know the sequence, a workflow is cheaper, faster and more predictable.</p><h2 id="general-tab" tabindex="-1">General tab <a class="header-anchor" href="#general-tab" aria-label="Permalink to &quot;General tab&quot;">​</a></h2><p><img src="'+s+'" alt="planejadores-detalhe"></p><p><strong>Objective</strong> is what you want to reach. It is stored as the default and can be replaced on each trigger — from the run screen, from a workflow or through the API.</p><p><strong>Success criterion</strong> is the text the model evaluates at the end of each round to decide whether it has arrived. Without it, the planner only stops at the limits, and will spend every iteration it can. Write something checkable: &quot;the file was written and the answer contains the computed total&quot; works; &quot;solve it well&quot; does not.</p><p><strong>Model</strong> is who plans and evaluates — not who executes. It is worth spending on a better model here than on the executors: a bad plan wastes every round that follows.</p><p><strong>Base agent</strong> (optional) is who performs the direct actions. Set one, and the planner inherits the MCPs, knowledge bases and tools that agent already has. Without it, direct actions use an ephemeral agent with nothing attached.</p><h3 id="executors" tabindex="-1">Executors <a class="header-anchor" href="#executors" aria-label="Permalink to &quot;Executors&quot;">​</a></h3><p>Still on the General tab: the agents and teams the planner may call. <strong>This list is what the model sees when it builds the plan</strong> — it can only delegate a step to someone listed here.</p><p>Each link carries a description of what that executor does. Write it with the reader in mind: the one choosing is the model, going by that text.</p><h3 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h3><p>These close the General tab. Four ceilings, all checked <strong>between steps</strong> — never in the middle of one:</p><table tabindex="0"><thead><tr><th>Limit</th><th>Default</th><th>What it is for</th></tr></thead><tbody><tr><td>Iterations</td><td>15</td><td>How many rounds of the cycle.</td></tr><tr><td>Steps</td><td>50</td><td>How many actions in total, across all rounds.</td></tr><tr><td>Tokens</td><td>—</td><td>Token budget for the run. No value, no ceiling.</td></tr><tr><td>Time</td><td>900 s</td><td>Maximum duration.</td></tr></tbody></table><p>These limits are not a configuration detail: a planner is a loop steered by a model, and the model may not converge. They are what guarantees the run ends.</p><h2 id="tools-tab" tabindex="-1">Tools tab <a class="header-anchor" href="#tools-tab" aria-label="Permalink to &quot;Tools tab&quot;">​</a></h2><p>Which internal operations the loop may call, and which database connections it may touch.</p><div class="warning custom-block"><p class="custom-block-title">With no data source released, the database functions are refused</p><p><code>db_query</code>, <code>db_insert</code>, <code>db_update</code>, <code>db_delete</code> and <code>db_upsert</code> are blocked <strong>before running</strong> when no connection is released. That is deliberate: without a list, the model would have to guess the connection ID, and guessing right would mean reaching a database the planner should not touch.</p></div><p>The list of available tools is in <a href="/pro-agent-hub-installer/en/funcoes/planejador">Planner</a>.</p><h2 id="run-and-executions-tabs" tabindex="-1">Run and Executions tabs <a class="header-anchor" href="#run-and-executions-tabs" aria-label="Permalink to &quot;Run and Executions tabs&quot;">​</a></h2><p><img src="'+r+'" alt="planejadores-execucao"></p><p>On <strong>Run</strong> you trigger the planner, optionally swapping the objective. The screen follows along live: the plan it built, each step with the executor it chose, what was observed and the evaluation of the round. Everything is stored, and the <strong>Executions</strong> tab keeps the history — you can reopen an old run and read the whole reasoning.</p><p>A run ends as <strong>completed</strong>, <strong>failed</strong>, <strong>cancelled</strong> or by <strong>limit reached</strong> — and, in the last case, which limit. If a planner keeps hitting <code>max_iterations</code>, the problem is almost never the ceiling: it is the success criterion or the description of the executors.</p>',25)])])}const m=t(i,[["render",l]]);export{b as __pageData,m as default};
